import React, { useState, useEffect } from 'react';
import { Menu, X, LayoutDashboard, Sun, Moon } from 'lucide-react';
import academyLogo from '../assets/logovighnaviacademy.png';

export default function Navbar({ activeScreen, setActiveScreen }) {
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [isDarkMode, setIsDarkMode] = useState(true);

  // Synchronize theme on load
  useEffect(() => {
    const savedTheme = localStorage.getItem('theme');
    const systemPrefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;

    if (savedTheme === 'light') {
      setIsDarkMode(false);
      document.documentElement.classList.remove('dark');
    } else {
      setIsDarkMode(true);
      document.documentElement.classList.add('dark');
    }
  }, []);

  const toggleTheme = () => {
    if (isDarkMode) {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('theme', 'light');
      setIsDarkMode(false);
    } else {
      document.documentElement.classList.add('dark');
      localStorage.setItem('theme', 'dark');
      setIsDarkMode(true);
    }
  };

  const navLinks = [
    { name: 'Home', screen: 'home' },
    { name: 'Career Guidance', screen: 'guidance' },
    { name: 'Workshops', screen: 'workshops' },
    { name: 'Courses', screen: 'courses' },
    { name: 'Internships', screen: 'internships' },
    { name: 'B.Tech Projects', screen: 'btech-projects' },
    { name: 'M.Tech Projects', screen: 'mtech-projects' },
    { name: 'About', screen: 'about' },
    { name: 'Contact', screen: 'contact' },
  ];

  const handleNav = (screen) => {
    setActiveScreen(screen);
    setMobileMenuOpen(false);
    window.scrollTo({ top: 0, behavior: 'smooth' });
  };

  return (
    <header className="sticky top-0 z-40 w-full transition-colors duration-300 bg-white/95 dark:bg-black/95 backdrop-blur-md border-b border-neutral-200 dark:border-neutral-800 text-black dark:text-white">
      <div className="max-w-7xl mx-auto px-4 sm:px-6 lg:px-8 h-20 flex items-center justify-between">
        
        {/* Brand / Logo */}
        <div 
          onClick={() => handleNav('home')} 
          className="cursor-pointer flex items-center space-x-3 group"
        >
          <img
            src={academyLogo}
            alt="Vighnavi Academy Logo"
            className="h-10 w-auto object-contain transition-transform duration-200 group-hover:scale-105"
            onError={(e) => {
              e.currentTarget.style.display = 'none';
              if (e.currentTarget.nextSibling) {
                e.currentTarget.nextSibling.style.display = 'flex';
              }
            }}
          />
          <div className="hidden w-10 h-10 rounded-xl bg-neutral-900 dark:bg-white text-white dark:text-black font-extrabold text-lg items-center justify-center border border-neutral-300 dark:border-neutral-700">
            VA
          </div>
          <div>
            <span className="text-xl font-extrabold tracking-tight text-black dark:text-white block">
              Vighnavi Academy
            </span>
            <p className="text-[11px] text-neutral-500 dark:text-neutral-400 tracking-wider uppercase font-medium">
              Wisdom • Knowledge • Success
            </p>
          </div>
        </div>

        {/* Desktop Navigation Links */}
        <nav className="hidden xl:flex items-center space-x-1">
          {navLinks.map((link) => {
            const isActive = activeScreen === link.screen;
            return (
              <button
                key={link.screen}
                onClick={() => handleNav(link.screen)}
                className={`px-3 py-2 rounded-lg text-sm font-semibold transition-all duration-150 ${
                  isActive
                    ? 'bg-black text-white dark:bg-white dark:text-black border border-black dark:border-white shadow-sm'
                    : 'text-neutral-700 dark:text-neutral-300 hover:text-black dark:hover:text-white hover:bg-neutral-100 dark:hover:bg-neutral-900'
                }`}
              >
                {link.name}
              </button>
            );
          })}
        </nav>

        {/* Right Section: Theme Toggle & Dashboard */}
        <div className="hidden xl:flex items-center space-x-3">
          {/* Black & White Theme Toggle Button */}
          <button
            onClick={toggleTheme}
            aria-label="Toggle Theme"
            title={isDarkMode ? 'Switch to Light Theme' : 'Switch to Dark Theme'}
            className="p-2.5 rounded-xl border border-neutral-300 dark:border-neutral-700 bg-neutral-100 dark:bg-neutral-900 hover:bg-neutral-200 dark:hover:bg-neutral-800 transition"
          >
            {isDarkMode ? (
              <Sun className="w-4 h-4 text-white" />
            ) : (
              <Moon className="w-4 h-4 text-black" />
            )}
          </button>

          {/* Student Dashboard Action Button */}
          <button
            onClick={() => handleNav('dashboard')}
            className="flex items-center space-x-2 bg-black hover:bg-neutral-800 dark:bg-white dark:hover:bg-neutral-200 text-white dark:text-black px-4 py-2.5 rounded-xl font-bold text-sm border border-black dark:border-white transition-all transform active:scale-95 shadow-sm"
          >
            <LayoutDashboard className="w-4 h-4" />
            <span>Dashboard</span>
          </button>
        </div>

        {/* Mobile Action Controls */}
        <div className="xl:hidden flex items-center space-x-2">
          {/* Mobile Theme Toggle Button */}
          <button
            onClick={toggleTheme}
            aria-label="Toggle Theme"
            className="p-2 rounded-lg border border-neutral-300 dark:border-neutral-700 bg-neutral-100 dark:bg-neutral-900"
          >
            {isDarkMode ? (
              <Sun className="w-5 h-5 text-white" />
            ) : (
              <Moon className="w-5 h-5 text-black" />
            )}
          </button>

          {/* Mobile Dashboard Button */}
          <button
            onClick={() => handleNav('dashboard')}
            className={`p-2 rounded-lg border transition-colors ${
              activeScreen === 'dashboard'
                ? 'bg-black text-white dark:bg-white dark:text-black border-black dark:border-white'
                : 'bg-neutral-100 dark:bg-neutral-900 text-black dark:text-white border-neutral-300 dark:border-neutral-700'
            }`}
            aria-label="Dashboard"
          >
            <LayoutDashboard className="w-5 h-5" />
          </button>

          {/* Mobile Menu Toggle Button */}
          <button
            onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
            className="p-2 rounded-lg bg-neutral-100 dark:bg-neutral-900 border border-neutral-300 dark:border-neutral-700 text-black dark:text-white"
            aria-label="Toggle Navigation Menu"
          >
            {mobileMenuOpen ? <X className="w-6 h-6" /> : <Menu className="w-6 h-6" />}
          </button>
        </div>
      </div>

      {/* Mobile Menu Dropdown */}
      {mobileMenuOpen && (
        <div className="xl:hidden bg-white dark:bg-black border-b border-neutral-200 dark:border-neutral-800 px-4 pt-2 pb-6 space-y-1">
          {navLinks.map((link) => {
            const isActive = activeScreen === link.screen;
            return (
              <button
                key={link.screen}
                onClick={() => handleNav(link.screen)}
                className={`w-full text-left px-4 py-3 rounded-lg text-sm font-semibold transition-colors ${
                  isActive
                    ? 'bg-black text-white dark:bg-white dark:text-black border border-black dark:border-white'
                    : 'text-neutral-700 dark:text-neutral-300 hover:bg-neutral-100 dark:hover:bg-neutral-900'
                }`}
              >
                {link.name}
              </button>
            );
          })}
        </div>
      )}
    </header>
  );
}
